INSERT INTO products (id,categoria,orden,titulo,descripcion,imagen,pdf_url,video_url) VALUES ('butler','hotelero',1,'eRoom Butler','Una potente solución Cloud Service 24/7 que permite a tus huéspedes, gestionar de forma autónoma y personalizada de su estancia.','/img/butler-mockup-card-1.webp','https://showroom.eroomsuite.com/wp-content/uploads/2025/01/eRoom-Butler-2026.pdf','https://showroom.eroomsuite.com/wp-content/uploads/2025/01/eRoom-Butler-Desk.mp4');
INSERT INTO products (id,categoria,orden,titulo,descripcion,imagen,pdf_url,video_url) VALUES ('hotspot','hotelero',2,'eRoom Hotspot','eRoom Hotspot es el portal cautivo de eRoom Suite, una solución integral de Wi-Fi que convierte cada acceso en una oportunidad de interacción','/img/hotspotmockup-card-2.webp','https://showroom.eroomsuite.com/wp-content/uploads/2025/01/eRoom-Hotspot-2026.pdf','https://showroom.eroomsuite.com/wp-content/uploads/2024/01/EROOM-HOTSPOT_1_1.mp4');
INSERT INTO products (id,categoria,orden,titulo,descripcion,imagen,pdf_url,video_url) VALUES ('tv','hotelero',3,'eRoom TV','Sistema interactivo que convierte la televisión del hotel en un centro de entretenimiento y servicios personalizados','/img/eroom-tv-card-3.webp','https://showroom.eroomsuite.com/wp-content/uploads/2025/01/eRoom-TV-2026.pdf','');
INSERT INTO products (id,categoria,orden,titulo,descripcion,imagen,pdf_url,video_url) VALUES ('cartas-digitales','hotelero',4,'Cartas Digitales','Cartas Digitales by eRoom Suite es la solución tecnológica que le permite a tu cliente visualizar desde su móvil precios de tu menú, tipos de platos con imágenes y videos.','/img/cartas-digitales-card-4.webp','https://showroom.eroomsuite.com/wp-content/uploads/2025/01/Cartas-Digitales.pdf','');
