INSERT INTO products (id,categoria,orden,titulo,descripcion,imagen,pdf_url,video_url) VALUES ('cdp-crm','huesped',6,'eRoom CDP / CRM','eRoom CRM es la mejor solución para el sector hospitality & B2B con el objetivo de incrementar el revenue y engagement de tu marca.','/img/crm-mockup-card-7.webp','https://showroom.eroomsuite.com/wp-content/uploads/2025/01/eRoom-CDP_CRM-2026.pdf','https://showroom.eroomsuite.com/wp-content/uploads/2025/01/eRoom-CDP_CRM.mp4');
INSERT INTO products (id,categoria,orden,titulo,descripcion,imagen,pdf_url,video_url) VALUES ('pms','huesped',7,'eRoom PMS','Brinda experiencias únicas a los huéspedes a través de procesos que garantizan la mejor atención en el menor tiempo y se adecuan a sus gustos.','/img/mockup-pms-card-8.webp','https://showroom.eroomsuite.com/wp-content/uploads/2024/01/eRoom-PMS.pdf','https://showroom.eroomsuite.com/wp-content/uploads/2024/01/EROOM-PMS2_1.mp4');
INSERT INTO products (id,categoria,orden,titulo,descripcion,imagen,pdf_url,video_url) VALUES ('signage','huesped',8,'eRoom Signage','eRoom Signage es la plataforma de señalética digital de eRoom Suite: una solución centralizada para gestionar y programar contenidos dinámicos en las pantallas de tu hotel.','/img/billboard-urban-mockup-card-6.webp','https://showroom.eroomsuite.com/wp-content/uploads/2025/01/eRoom-Signage-2026.pdf','https://showroom.eroomsuite.com/wp-content/uploads/2024/01/EROOM-SIGNAGE_1_1.mp4');
