INSERT INTO products (id,categoria,orden,titulo,descripcion,imagen,pdf_url,video_url) VALUES ('bi','huesped',10,'eRoom BI','Conoce el estado actual de tu negocio y realiza proyecciones a futuro tomando todas las variables que creas pertinentes y el periodo de tiempo que desees evaluar y/o proyectar.','/img/bi-mockup-card-11.webp','https://showroom.eroomsuite.com/wp-content/uploads/2025/01/eRoom-BI.pdf','https://showroom.eroomsuite.com/wp-content/uploads/2025/01/Eroom-Video-Bi.mp4');
INSERT INTO products (id,categoria,orden,titulo,descripcion,imagen,pdf_url,video_url) VALUES ('assistant','huesped',11,'eRoom Assistant','eRoom Assistant es la solución más avanzada del mercado para ahorrar costes en suministros mediante controles de presencia y un algoritmo de eficiencia.','/img/assistant-mockup-card-9.webp','https://showroom.eroomsuite.com/wp-content/uploads/2024/01/eRoom-Assistant.pdf','');
INSERT INTO products (id,categoria,orden,titulo,descripcion,imagen,pdf_url,video_url) VALUES ('network-solutions','huesped',12,'eRoom Network Solutions','eRoom Network Solutions despliega ecosistemas de red desde arquitecturas GPON hasta entornos de ciberseguridad avanzada diseñados para la alta demanda operativa de un hotel moderno.','/img/network-mockup-card-13.webp','https://showroom.eroomsuite.com/wp-content/uploads/2025/01/eRoom-Network-Solutions-2026.pdf','https://showroom.eroomsuite.com/wp-content/uploads/2025/01/eRoom-Ns-2025.mp4');
INSERT INTO products (id,categoria,orden,titulo,descripcion,imagen,pdf_url,video_url) VALUES ('erp','huesped',13,'eRoom ERP','Automatiza y gestiona todos los procesos operativos de tu negocio en un solo lugar.','/img/erp-mockup-card-14.webp','https://showroom.eroomsuite.com/wp-content/uploads/2024/01/eRoom_ERP.pdf','');
INSERT INTO products (id,categoria,orden,titulo,descripcion,imagen,pdf_url,video_url) VALUES ('hub','huesped',14,'eRoom HUB','eRoom HUB es la herramienta On Cloud que te permite conectar tus aplicaciones de terceros con el universo de soluciones eRoom para una colaboración más rápida, sencilla y segura.','/img/mockup-hub-card-12.webp','https://showroom.eroomsuite.com/wp-content/uploads/2024/01/eRoom-HUB.pdf','');
